    exp: now + 300,
    ...(p.grant.name !== undefined ? { name: p.grant.name } : {}),
    ...(p.grant.picture !== undefined ? { picture: p.grant.picture } : {}),
    ...(p.grant.email !== undefined ? { email: p.grant.email, email_verified: true } : {}),
  };
}

